# 第 3 批：卦 18-26（蛊、临、观、噬嗑、贲、剥、复、无妄、大畜）

HEXAGRAMS = {
  "18": {
    "zh": "蛊卦下巽上艮，积弊等待整治。它讲的是收拾前人留下的烂摊子——拨乱反正，但动手之前先要把情况弄明白。",
    "en": "Gu is compliance below, mountain above — accumulated corruption awaiting repair. It's about cleaning up a mess left behind: set things right, but understand the situation before you act.",
    "ja": "蠱は下が巽、上が艮。積み重なった弊が治めを待つ。先人の残した乱れを直すことを表す——乱れを正すが、手をつける前に事情を明らかにすること。",
  },
  "19": {
    "zh": "临卦下兑上坤，以柔临刚。它讲的是居上位者的德行——靠正道而不是靠权势去临民；八月是盛极之时，借此警戒盈满。",
    "en": "Lin is joy below, yielding above — softness approaching strength. It's the virtue of those in high position: lead by what's right, not by power. The eighth month is the peak of fullness — a warning against overflowing.",
    "ja": "臨は下が兑、上が坤。柔で剛に臨む。上位者の徳を表す——勢いではなく正しさで人に臨む。八月は盛りの極みで、満ちることへの戒め。",
  },
  "20": {
    "zh": "观卦下坤上巽，观看而不行动。它讲的是省察的道理——观国之光、观人也观己；要看风化好不好，先看自己。",
    "en": "Guan is yielding below, compliance above — observing without acting. It's about examination: observe the light of the state, observe others and yourself. To read the customs, start with yourself.",
    "ja": "観は下が坤、上が巽。見てまだ動かない。省察の道理を表す——国の光を見、人を見、自分も見る。風俗の良し悪しを知るには、まず自分を見ること。",
  },
  "21": {
    "zh": "噬嗑卦下震上离，明罚正法。它讲的是排除障碍要用刑罚——像咬碎硬物才能合上；障碍不除，事情就办不成。",
    "en": "Shike is movement below, clarity above — clear penalties, upright law. It's about removing obstacles through justice: you must chew through the hard bit to close. Remove the obstacle and the thing can be done.",
    "ja": "噬嗑は下が震、上が離。罰を明らかにし法を正す。障害を除くのに刑を用いることを表す——硬いものを噛み砕いて初めて合う。障害を除かなければ、事は成らない。",
  },
  "22": {
    "zh": "贲卦下离上艮，讲文饰之道。它讲的是装饰要建立在质朴之上——贲是文饰，但文胜过质就伤了根本，所以朴素的白贲最上乘。",
    "en": "Bi is clarity below, mountain above — the way of adornment. It's about ornament built on substance: Bi means decoration, but when appearance outruns substance it harms the root, so plain white adornment is highest.",
    "ja": "賁は下が離、上が艮。飾りの道を表す。飾りは質の上に立つべきもの——賁とは文飾だが、文が質に勝てば本を傷つける。だから素白の賁が最も良い。",
  },
  "23": {
    "zh": "剥卦下坤上艮，五阴剥落一阳。它讲的是剥落的道理——剥的时候要止，留着那颗大果子不吃，等待阳气回来。",
    "en": "Bo is yielding below, mountain above — five yin stripping one yang. It's about erosion: when things are stripping away, stop; leave the great fruit uneaten and wait for the yang to return.",
    "ja": "剥は下が坤、上が艮。五つの陰が陽を剥がす。剥げ落ちる道理を表す——剥れる時は止まり、大きな実を食わずに残し、陽の戻りを待つ。",
  },
  "24": {
    "zh": "复卦下震上坤，一阳来复。它讲的是回归的道理——走错不远就回头，就不会有大悔恨；初爻是全卦关键，能察觉苗头就近于神明了。",
    "en": "Fu is movement below, yielding above — one yang returning. It's about coming back: turn around before you've gone far and you avoid great regret. The first line is the key to the whole hexagram — catching the earliest sign is near-divine.",
    "ja": "復は下が震、上が坤。一つの陽が戻る。立ち返る道理を表す——遠く行く前に戻れば、大きな悔いはない。初爻が全卦の鍵で、兆しを察するのは神に近い。",
  },
  "25": {
    "zh": "无妄卦下震上乾，不妄为。它讲的是真诚光明的道理——无妄就是不计较、不设机心，顺着天道自然而行。",
    "en": "Wuwang is movement below, strength above — acting without falsity. It's about sincerity and clarity: Wuwang means no calculating, no hidden agenda, simply following the natural way of heaven.",
    "ja": "無妄は下が震、上が乾。みだりに為さない。誠実で明るい道理を表す——無妄とは策をめぐらさず、下心を置かず、天の自然に従うこと。",
  },
  "26": {
    "zh": "大畜卦下乾上艮，大有蓄积。它讲的是厚积的道理——每天更新自己的德行，积蓄而不急着发用，这就是畜。",
    "en": "Dachu is strength below, mountain above — great accumulation. It's about deep storing: renew your virtue daily, accumulating without rushing to spend it — that's Chu.",
    "ja": "大畜は下が乾、上が艮。大いに蓄える。厚く積む道理を表す——日々その徳を新たにし、積んで急に使わない。それが畜だ。",
  },
}

LINES = {
  # 18 蛊
  "18-0": {"zh": "你在最底下，是蛊的开始，继承父辈留下的败坏去收拾它。前人的积弊，靠后人来整治，过失就能补——治弊的开头有危险，之后才安。", "en": "You're at the bottom, the start of Gu, inheriting a parent's ruin and setting it right. The corruption of predecessors repaired by successors — the fault can be mended. The start of repair is dangerous; afterward comes peace.", "ja": "一番下で、蠱の初め。先代の親の崩れを継いで治める。前人の積弊を後人が治せば、過ちは補える。治め始めは危うく、その後安くなる。"},
  "18-1": {"zh": "你在下卦正中，上应六五，整治母亲留下的弊，事情在内。治内部的弊不能直来直去——刚强又能柔和，委曲周旋才能深入。", "en": "You're at the center of the lower trigram, matched with the sixth line above, repairing a mother's corruption — an internal matter. Internal repair can't be done head-on — strong yet soft, you must wind your way in.", "ja": "下卦の中央にいて、六五に応じ、母の残した弊を治める。内なる事だ。内の弊はまっすぐには直せない——剛で柔を作い、屈折して初めて入れる。"},
  "18-2": {"zh": "你在下卦最上面，刚强却不居中，治弊过了头。治弊不能没有刚强，但刚过头就生悔——不过你的志向是正的，所以过失还不至于大。", "en": "You're at the top of the lower trigram — rigid and off-center, overdoing the repair. Repair needs firmness, but too much breeds regret — yet your aim is right, so the fault won't be great.", "ja": "下卦の最上部にいて、剛だが中を外れ、弊を治めすぎた。治めるのに剛が要らないわけにはいかないが、剛が過ぎれば悔いが生まれる。ただ志が正しいので、過ちは大きくならない。"},
  "18-3": {"zh": "你在上卦下面，柔弱又不正，治弊反而宽容放纵，等于助长它。明知有弊却不治，又宽纵让它扩大，这是养痈遗患——这样下去，羞吝是看得见的。", "en": "You're below the upper trigram — soft and improper, repairing by being lenient, which feeds the problem. Knowing the corruption but not fixing it, then indulging it further, is nursing the disease. Keep going and the disgrace is plain.", "ja": "上卦の下にいて、柔で正しくなく、弊を寛大にしてかえって助長する。弊を知りながら治さず、さらに寛くして大きくするのは、蠱を養うことだ。このまま行けば、恥は目に見えている。"},
  "18-4": {"zh": "你身居尊位，柔和中正，任用九二的刚强来治弊。治弊不必自己动手，用贤人去治、功劳归到自己身上，这叫善于用人而获誉。", "en": "You're in the place of honor, soft and centered, appointing the rigidity of the second line to repair the corruption. Repair needn't come from you — use the worthy and take the credit: that's earning praise through others.", "ja": "尊い位にいて、柔らかく中を得て、九二の剛を用い蠱を治める。弊を治めるのに自分でなくてもよい。賢者を使って治め、功が上に帰る——これを誉を用いるという。"},
  "18-5": {"zh": "你到了卦的顶，置身蛊之外，不被俗世的事情役使。处在积弊极深的时候不出来做官，洁身自守——可贵的是这种志向，不是那个位子。", "en": "You're at the top of the hexagram, outside the corruption, not hired out to worldly affairs. In an age of deep decay you don't take office, keeping yourself clean. What's honored is this resolve, not the position.", "ja": "卦の頂点にいて、蠱の外にあり、世の事に使われない。弊の極まった世に出仕せず、身を清く守る。尊いのはその志で、その位ではない。"},
  # 19 临
  "19-0": {"zh": "你在最底下，与六四正应，用诚意去感化、居高临下。临民先要用诚去感，感了才有应——靠力量压人，人家不会亲近你。", "en": "You're at the bottom, properly matched with the fourth line, winning over those below with sincerity. Approach people by touching their hearts first — only after they're moved do they respond. Pressure won't make them come close.", "ja": "一番下にいて、六四と正しく応じ、誠で感化して下に臨む。人に臨むにはまず誠で感ずる——感じて初めて応じる。力で臨めば、人は我に親しまない。"},
  "19-1": {"zh": "你在下卦正中，上应六五，刚健中正而能感，临人不偏。刚而得中，感化就正——用正道去感召下面，就无往而不顺。", "en": "You're at the center of the lower trigram, matched with the sixth line, strong and centered in your influence, approaching without bias. Strength with centrality makes your influence right — move those below by what's right and everywhere goes smoothly.", "ja": "下卦の中央にいて、六五に応じ、剛中で感ずる。臨みに偏りがない。剛で中を得れば、その感は正しい——正しさで下を感じれば、行く先すべて順調だ。"},
  "19-2": {"zh": "你在下卦最上面，不中不正，用甜言蜜语去临人。用好听的话取悦人却没有实质，这叫甘临——既然知道不对而发愁，就可以改。", "en": "You're at the top of the lower trigram — off-center and improper, approaching people with sweet talk. Pleasing with words but no substance is called sweet approach. Once you know it's wrong and feel concern, you can change.", "ja": "下卦の最上部にいて、中も正も外れ、甘い言葉で人に臨む。言葉で人を悦ばせて実がない——これを甘臨という。それが非と知って憂えれば、改められる。"},
  "19-3": {"zh": "你在上卦下面，柔顺得正而下应初九，亲自到下面去。临民贵在亲身前往，不只是摆位子——亲自到下面，情意就不会隔。", "en": "You're below the upper trigram, soft and proper, reaching down to the first line — going there in person. Approaching people means going yourself, not just holding the position — when you come down in person, no distance remains.", "ja": "上卦の下にいて、柔らかく正しく下の初九に応じ、自らその場へ赴く。臨むには身が至ることが肝心で、位だけではない。自ら下に臨めば、情は隔たらない。"},
  "19-4": {"zh": "你身居尊位，柔和中正而下应初九，不刚愎自用而用人。大君主的智慧在于知人而不自用——任用贤者去临下，不刻意作为而事自成。", "en": "You're in the place of honor, soft and centered, reaching down to the first line, not relying on yourself but using others. A great ruler's wisdom is knowing people, not self-reliance — appoint the worthy to govern below, and things get done without forcing.", "ja": "尊い位にいて、柔らかく中を得て下の初九に応じ、自ら用いず人を用いる。大君の知は人を知ることにあり、自分を用いない。賢者を任じて下に臨めば、為さずとも事は成る。"},
  "19-5": {"zh": "你到了卦的顶，临到了头，以柔居上而待下深厚。临下之道，久了不倦怠、厚道不刻薄——用敦厚去临民，最终没有祸患。", "en": "You're at the top of the hexagram, Lin at its end, soft above and generous to those below. The way to govern: long without tiring, generous without stinginess — approach with kindness and there's no trouble at the end.", "ja": "卦の頂点にいて、臨は終わり、柔で上に居り下に厚い。下に臨む道は、久しくても倦まず、厚くて薄くない。敦厚で臨めば、終わりに禍はない。"},
  # 20 观
  "20-0": {"zh": "你在最底下，离九五最远，所见浅薄，像小孩子看热闹。见识浅，对小人物还不算过错；可要是君子也这样，就成不了什么事。", "en": "You're at the bottom, farthest from the fifth line, your view shallow — like a child watching the show. Shallow seeing is no great fault in a small person; but a gentleman like this can't accomplish anything.", "ja": "一番下にいて、九五から最も遠く、見るところが浅い。童子の見物のようだ。見識が浅いのは小人なら大過ではないが、君子がそうでは何も成せない。"},
  "20-1": {"zh": "你在下卦正中，从缝隙里窥看九五，所见狭窄又不正。从旁边偷看，看得不全——柔顺的人这样还能自守，君子这样做，道就鄙陋了。", "en": "You're at the center of the lower trigram, peeking at the fifth line through a gap — narrow and crooked sight. Watching from the side gives an incomplete view. For a soft person this can still be a guard, but for a gentleman it's a mean way.", "ja": "下卦の中央にいて、九五を隙間から覗き見る。見るところが狭く正しくない。脇から盗み見れば見えるのは一部分。柔順な者ならまだ守りになるが、君子ではその道は卑しい。"},
  "20-2": {"zh": "你在下卦最上面，靠近九五，反过来观察自己的行为。看别人不如看自己——察清自己的得失，然后才能决定进退。", "en": "You're at the top of the lower trigram, near the fifth line, turning to observe your own conduct. Watching others is not as good as watching yourself — examine your own gains and losses, then decide when to move or stop.", "ja": "下卦の最上部にいて、九五に近く、かえって己の行いを観る。人を見るより己を見るに如かず。自分の得失を察して、初めて進退を決められる。"},
  "20-3": {"zh": "你在上卦下面，靠近九五的君主，观察国家的盛德。看到国家兴盛，就可以进而为宾——所观的格局大，进取就不苟且。", "en": "You're below the upper trigram, near the fifth-line ruler, observing the state's abundant virtue. Seeing the state flourish, you may advance as a guest. The scale of what you observe is great, so your advance isn't careless.", "ja": "上卦の下にいて、九五の君に近く、国の盛んな徳を観る。国の盛りを見れば、進んで宾となることができる。観るものが大きいので、進み方もいい加減にならない。"},
  "20-4": {"zh": "你身居尊位，得正又近九五，观察自己的行为给天下人看。居上位的人，省察自己的得失，作为天下观察的榜样——自己正了，人自然就被感化。", "en": "You're in the place of honor, proper and near the fifth line, observing your own conduct as an example to the world. Those above examine their own gains and losses, becoming what the world observes — when you yourself are right, people are transformed.", "ja": "尊い位にいて、正を得て九五に近く、己の行いを観じて人に示す。上位者は己の得失を省み、天下の観るところとする。自ら正しければ、人は自然に化される。"},
  "20-5": {"zh": "你到了卦的顶，置身观之外，不当事却被人看着行为。位子虽不在，德行仍被人仰慕——不懈地修养自己，这就是观的终点。", "en": "You're at the top of the hexagram, outside Guan, holding no office yet watched by others. Though without position, your virtue is looked up to — cultivate yourself without slackening. That's the end of Guan.", "ja": "卦の頂点にいて、観の外にあり、事を担当しないが行いが人に見られる。位になくても徳は人に仰がれる。修己を懈らぬこと——これが観の終わりだ。"},
  # 21 噬嗑
  "21-0": {"zh": "你在最底下，是噬嗑的开始，小惩就能大诫，所以先灭掉脚趾。在小处惩戒，过失就不至于变大——刑罚一开始是用来止住苗头，不是追究到底。", "en": "You're at the bottom, the start of Shike — a small punishment gives a great warning, so the feet are first restrained. Correct at the small stage and faults won't grow. Punishment at first stops the beginning, not pursues the end.", "ja": "一番下で、噬嗑の初め。小さく懲らしめて大いに戒める。だから足の趾を滅ずる。小さなうちに懲らしめれば過ちは大きくならない。刑のはじめは、その兆しを止めることで、最後まで追うことではない。"},
  "21-1": {"zh": "你在下卦正中，柔顺得正而断狱，容易咬断。所治的案子浅、当事人又中正，即使办得深也不会冤枉——中正的人可以胜任刑罚。", "en": "You're at the center of the lower trigram, soft and proper in judging — the hard bit is easy to bite through. The case is shallow and the person upright, so even a thorough handling won't wrong them. Centered and proper people can handle punishment.", "ja": "下卦の中央にいて、柔らかく正しく獄を治める。噛み砕きやすい。治めるものが浅く、その人も中正なら、深く処しても枉げない。中正な者は刑を任せられる。"},
  "21-2": {"zh": "你在下卦最上面，不中不正，碰上难啃的案子反而受伤。办难事而才干不称，会有点小麻烦——不过你位柔、不会一直错到底，所以可以免。", "en": "You're at the top of the lower trigram — off-center and improper, biting a hard case and getting hurt instead. Taking a hard task with inadequate ability brings small trouble — but your place is soft and you won't persist in error, so you're let off.", "ja": "下卦の最上部にいて、中も正も外れ、噛みにくいものを治めてかえって傷つく。難しい事を才に合わず行えば、少し不都合が出る。ただ位が柔で最後まで過ちを続けないので、免れる。"},
  "21-3": {"zh": "你在上卦下面，去啃难啃的，刚直自持。办难事要有刚直之才，而且要以艰难之心去做——不把它当难事，就担不起这个任。", "en": "You're below the upper trigram, biting the hard bit, holding yourself rigid and upright. Hard tasks need upright firmness, carried out with a sense of difficulty — unless you treat it as hard, you can't bear the charge.", "ja": "上卦の下にいて、噛みにくいものを噛み、剛直を自ら保つ。難しい事を治めるには剛直な才能が要り、しかも艱難の心で行う。艱難としなければ、その任に勝てない。"},
  "21-4": {"zh": "你在尊位旁边，是断狱的主爻，刚健却居柔位。断狱贵在刚而能柔、中而能正——心里常存危惧，判断就不会出差错。", "en": "You're beside the place of honor, the main judge, strong but in a soft place. Judging values strength that can be soft, centrality that stays right — keep fear in your heart and your ruling won't go wrong.", "ja": "尊位の傍らにいて、獄を治める主爻となり、剛でありながら柔の位に居る。獄を裁ぶのは剛で柔を作え、中で正を保つことが肝心。心に危惧を抱けば、その断りは違えない。"},
  "21-5": {"zh": "你到了卦的顶，积恶到了头，刑罚落到首恶身上，蒙蔽已经很深。小惩不知警戒，终成大恶——耳朵听不进过失，所以这个蒙蔽解不开了。", "en": "You're at the top of the hexagram, accumulated evil at its end, punishment reaching the ringleader, the blindness deep. Small correction unheeded grows into great evil — the ear won't hear fault, so the blindness can't be undone.", "ja": "卦の頂点にいて、悪が積もりきり、刑が首に及び、蔽いがすでに深い。小さな懲戒を戒めず、大悪に至る。耳が過ぎを聞かないので、その蔽いは解けない。"},
  # 22 贲
  "22-0": {"zh": "你在最底下，是贲的开始，舍了车不坐，安安稳稳走路。装饰不在于外物多华丽——把能坐的车舍掉而步行，是安于自己的本分。", "en": "You're at the bottom, the start of Bi — leaving the carriage and walking contentedly. Adornment isn't about outward splendor — giving up a ride you could take and walking is resting in your own station.", "ja": "一番下で、賁の初め。車を捨てて歩くことを安んずる。飾りは外物の盛りにあるのではない。乗れる車を捨てて歩くのは、自分の分に安んずることだ。"},
  "22-1": {"zh": "你在下卦正中，上承九三，随着刚健而动。文饰不能独自立住，必须附着在质朴上——随着那刚健往上走，这是文饰的正当用法。", "en": "You're at the center of the lower trigram, receiving the third line, moving along with the strong. Adornment can't stand alone — it must attach to substance. Rising with that strength is the proper use of ornament.", "ja": "下卦の中央にいて、九三を承け、剛に従って動く。文はひとりで立てず、必ず質に付く。その剛に従って上るのが、文の正しい使い方だ。"},
  "22-2": {"zh": "你在下卦最上面，夹在两阴之间，文饰极盛却能润泽适度。文胜了容易沉溺——能常守其正，装饰就不成为害。", "en": "You're at the top of the lower trigram, between two yin lines, adornment at its height yet moistened with restraint. When ornament wins it's easy to drown — if you keep to what's right, the adornment won't harm.", "ja": "下卦の最上部にいて、二つの陰の間にあり、文飾が盛んなのに潤いがある。文が勝てば溺れやすい。常に正を守れれば、その飾りは害とならない。"},
  "22-3": {"zh": "你在上卦下面，与初九相应，反而回到朴素。文到了极处就返璞，饰到尽头就归于素——这个素，正是贲的本体。", "en": "You're below the upper trigram, matched with the first line, returning instead to plainness. At the extreme of ornament you return to substance; when adorning ends, plainness remains — and that plainness is Bi's true body.", "ja": "上卦の下にいて、初九に応じ、かえって素に返る。文が極まれば質に返り、飾りが尽きれば素に帰る。この素こそ、賁の本体だ。"},
  "22-4": {"zh": "你在尊位旁边，柔顺得正而崇尚质朴，所贲的很薄。重质不重文，礼虽薄，情意却厚——爱好如此，终究有所得。", "en": "You're beside the place of honor, soft and proper, valuing substance — your adornment is slight. Favoring substance over show, the rite is thin but the feeling is deep. With such tastes, you gain in the end.", "ja": "尊位の傍らにいて、柔らかく正しく質を尊び、賁うところは薄い。文より質を尊べば、礼は薄くても意は厚い。好みがこうであれば、終わりに得るところがある。"},
  "22-5": {"zh": "你到了卦的顶，贲到了头，装饰到了极处归于无色。最高的装饰，就是没有颜色——文返回到质，这是贲道的完成。", "en": "You're at the top of the hexagram, Bi at its end, adornment returning to colorless. The highest adornment is no color at all — ornament returning to substance: that's Bi brought to completion.", "ja": "卦の頂点にいて、賁は終わり、飾りが極まって無色に帰る。飾りの極みとは、色がないこと。文が質に返る——これが賁の道の完成だ。"},
  # 23 剥
  "23-0": {"zh": "你在最底下，是剥的开始，祸害从下往上。剥一定从下面起，根基坏了上面跟着倒——看见苗头不救，到最后一定波及。", "en": "You're at the bottom, the start of Bo — damage rising from below. Erosion always starts at the base; when the foundation rots, the top falls with it. See the beginning and don't rescue it, and the end is sure to reach you.", "ja": "一番下で、剥の初め。害は下から上へ及ぶ。剥れは必ず下から始まり、基盤が壊れれば上も続く。兆しを見て救わなければ、終わりには必ず及ぶ。"},
  "23-1": {"zh": "你在下卦正中，剥已经到了床的边沿，祸害渐渐加深。剥越深，坏的部位越往上——只知渐渐剥落却不知止，道就一天天消减。", "en": "You're at the center of the lower trigram, erosion reaching the edge of the bed, damage deepening. The deeper it strips, the higher the rot — knowing only the gradual loss and not stopping, your way thins day by day.", "ja": "下卦の中央にいて、剥れは床の縁に及び、害はだんだん深まる。剥れるほど壊れる所は上へ移る。だんだん剥げることを知っても止めなければ、道は日々減っていく。"},
  "23-2": {"zh": "你在下卦最上面，唯独与上九相应，只有你不剥阳。跟大家一样作恶，唯独你依从正道，这是能自外于流俗——同流而不被染污，可以免祸。", "en": "You're at the top of the lower trigram, uniquely matched with the top line, the only one not stripping the yang. While all others do wrong, you follow what's right — setting yourself apart. In the current yet unstained, you can escape.", "ja": "下卦の最上部にいて、上九だけと応じ、ただあなた一人が陽を剥がない。皆と同じ悪に加わらず、ただ正に従う——それが流俗と異なること。同じ流れにいて汚れなければ、禍を免れられる。"},
  "23-3": {"zh": "你在上卦下面，剥已经到了皮肤，切近自身。剥到身上就没救了——祸的到来，不是一朝一夕积成的。", "en": "You're below the upper trigram, erosion reaching the skin, close to your body. When stripping reaches you, it can't be saved — disaster's arrival isn't a single day's accumulation.", "ja": "上卦の下にいて、剥れは肌に及び、身に迫る。身に剥れが及べば救えない。禍の来るのは、一朝一夕の積もりではない。"},
  "23-4": {"zh": "你在尊位旁边，率群阴承奉上九，像一串鱼那样有序。群阴相率跟从阳，各安其位互不侵犯，剥就能止住。", "en": "You're beside the place of honor, leading the yin lines in serving the top line, orderly like a string of fish. When the yin lines follow the yang in ranks, each keeping its place without encroaching, erosion can be stopped.", "ja": "尊位の傍らにいて、群陰を率いて上九を承け、魚を貫くように順序正しい。群陰が陽に従って、それぞれの位を安んじて侵し合わなければ、剥れは止む。"},
  "23-5": {"zh": "你到了卦的顶，剥到了头，独存一个阳爻，像硕大的果子。剥到极处只剩一阳独存，复兴就靠它——君子得到它就能承载，小人连依靠都失去。", "en": "You're at the top of the hexagram, Bo at its end, one yang line left alone, like a great fruit. At erosion's peak a single yang survives — renewal rests here. The gentleman gains it and carries on; the small man loses even his support.", "ja": "卦の頂点にいて、剥れは終わり、ただ一つの陽が残り、大きな実のようだ。剥れの極に一陽だけが残る。その復活はここにある——君子はこれを得て載せ、小人は頼るものまで失う。"},
  # 24 复
  "24-0": {"zh": "你在最底下，是复的开始，迷失不远就回来了。错了马上回头，不至于悔——复贵在快，快了损失就小。", "en": "You're at the bottom, the start of Fu — lost but not far before returning. Wrong and back at once, you avoid regret. Return values speed; the faster, the smaller the loss.", "ja": "一番下にいて、復の初め。迷って遠く行かぬうちに戻る。失してすぐ戻れば、悔いには及ばない。復すのは速さが肝心で、速ければ損は小さい。"},
  "24-1": {"zh": "你在下卦正中，柔顺得正而下比初九，能停下来归复。靠近善人而能自休归善，这是从善的美德——柔而能下人，所以得到休美。", "en": "You're at the center of the lower trigram, soft and proper, close to the first line, able to stop and return. Near a good person, you rest and return — the beauty of following good. Soft and willing to be low, you gain repose.", "ja": "下卦の中央にいて、柔らかく正しく初九に比し、休んで復える。善人に近づいて自ら休めば復る——善に従う美しさだ。柔で人より下になれるので、休美を得る。"},
  "24-2": {"zh": "你在下卦最上面，不中不正，屡次迷失屡次回来。屡失屡复，虽危却不至于沉溺——复得频繁，说明志向还没定下来。", "en": "You're at the top of the lower trigram — off-center and improper, losing and returning again and again. Repeated loss and return, though dangerous, won't drown you — returning often just means your aim isn't settled.", "ja": "下卦の最上部にいて、中も正も外れ、たびたび迷ってたびたび戻る。失しては復ることを繰り返せば、危くても溺れはしない。復るのが多いのは、志がまだ定まらないだけだ。"},
  "24-3": {"zh": "你在上卦下面，众阴之中唯独与初九相应。大家都迷了，唯独我回头，这是从正不从众——独行者志向坚定。", "en": "You're below the upper trigram, the only yin matched with the first line. While all are lost, I alone return — following what's right, not the crowd. The one who walks alone has a firm aim.", "ja": "上卦の下にいて、多くの陰の中でただ初九に応じる。皆が迷う中、ただ私だけが戻る——正に従って衆に従わない。独り行く者は志が堅い。"},
  "24-4": {"zh": "你在尊位旁边，柔和中正而能自己归复，复得深厚牢固。复在于中，就复得厚——厚了就不动摇，所以可以无悔。", "en": "You're beside the place of honor, soft and centered, able to return yourself — deep and firm. Returning through centrality makes it deep; deep means unshakable, so you can be without regret.", "ja": "尊位の傍らにいて、柔らかく中を得て自ら復え、その復りは厚く固い。中によって復れば、その復りは厚い。厚ければ揺るがないので、悔いなくて済む。"},
  "24-5": {"zh": "你到了卦的顶，复到了头却迷途不返，离初九最远。迷了不回头，是终身不知反——这个祸不是外面来的，是自己招的。", "en": "You're at the top of the hexagram, Fu at its end yet still lost and not returning, farthest from the first line. Lost and not returning is never turning back your whole life — this trouble isn't from outside; you brought it on yourself.", "ja": "卦の頂点にいて、復は終わったのに迷って返らず、初九から最も遠い。迷って戻らないのは、終身返ることを知らないこと。この患いは外から来たのではなく、自ら招いたものだ。"},
  # 25 无妄
  "25-0": {"zh": "你在最底下，是无妄的开始，以刚健而动，动出于诚。凭诚而不是凭私去行动，前往没有不合——无妄的前往，是顺着本心。", "en": "You're at the bottom, the start of Wuwang, moving with strength, moving from sincerity. Acting from faith not from self-interest, you go nowhere amiss. The Wuwang journey follows the original heart.", "ja": "一番下にいて、無妄の初め。剛をもって動き、その動きは誠による。私ではなく誠で動けば、行く先すべて合う。無妄の往きは、本心に従うことだ。"},
  "25-1": {"zh": "你在下卦正中，柔顺得正，不指望收获才去做。不为报酬而做，这才叫无妄——想着报答才去做，心就已经妄了。", "en": "You're at the center of the lower trigram, soft, proper and compliant, acting without expecting a harvest. Acting without motive of reward — that's Wuwang. If you go hoping for payment, your heart is already false.", "ja": "下卦の中央にいて、柔らかく正しく従う。獲りを期さずに行く。報いを求めず為す、それが無妄だ。報われんがために往けば、心はすでに妄っている。"},
  "25-2": {"zh": "你在下卦最上面，不中不正，所处不当。灾祸有时不是你造成的，这叫无妄之灾——但处在不当的位置，就更容易碰上。", "en": "You're at the top of the lower trigram — off-center and improper, in a wrong place. Sometimes disaster isn't of your making — that's the 'unnecessary' calamity of Wuwang. But in an improper place you meet it more easily.", "ja": "下卦の最上部にいて、中も正も外れ、処する所が当たらない。災いには自分のせいでないものもある——これを無妄の災という。ただ位に当たらなければ、それに遭いやすい。"},
  "25-3": {"zh": "你在上卦下面，刚健却居柔位，可以固守正道。以刚处柔而不妄动，守住本有的正，就能无过。", "en": "You're below the upper trigram, strong in a soft place, able to hold fast to what's right. Strength in softness without rash movement, keeping your native rightness — you can be without fault.", "ja": "上卦の下にいて、剛で柔の位に居り、正を固く守れる。剛を柔に処して妄りに動かず、もともとの正を守れば、過ちはない。"},
  "25-4": {"zh": "你身居尊位，刚健中正，你的病不是自己招来的。无妄而来的病，不用治自己会好——用药去攻它，反而生出病来。", "en": "You're in the place of honor, strong and centered, your illness not self-inflicted. An Wuwang affliction heals on its own without treatment — attacking it with medicine only creates illness.", "ja": "尊い位にいて、剛中で正しく、その病は自ら招いたものではない。無妄で来た病は、治さずとも自ずと解ける。薬で攻めれば、かえって病を生む。"},
  "25-5": {"zh": "你到了卦的顶，无妄到了头，处极还要前行。时机已极还想动，即使无妄也会困穷——安静守着，才是本分。", "en": "You're at the top of the hexagram, Wuwang at its end, at the peak yet still wanting to go. When the time is spent and you still want to move, even blamelessness runs dry — staying still is your proper part.", "ja": "卦の頂点にいて、無妄は終わり、極にあってまだ行こうとする。時はすでに極まってまだ動きたがれば、無妄でも行き詰まる。静かに守るのが、自分の分だ。"},
  # 26 大畜
  "26-0": {"zh": "你在最底下，被艮止住，刚健爱进，知危而止。前进有危险就停下，停下不是怯，是等时机——止而不妄进，就足以养你的德。", "en": "You're at the bottom, stopped by the mountain — strong and eager to advance, but knowing danger you stop. When advance is dangerous, stopping isn't cowardice; it's waiting for the time. Stopping without rash progress is enough to nourish your virtue.", "ja": "一番下にいて、艮に止められ、剛で進みたがるが、危を知って止まる。進んで危うければ止む——止まるのは臆病ではなく、時を待つことだ。妄りに進まず止まれば、その徳を養うに足る。"},
  "26-1": {"zh": "你在下卦正中，刚健中正却不前进，自己卸下车轴。中而能自止，不用别人来止你——自己能止的，那个止才牢固。", "en": "You're at the center of the lower trigram, strong and centered but not advancing, removing your own axle. Centered and able to stop yourself, you don't need others to stop you — self-imposed stopping is the firmest.", "ja": "下卦の中央にいて、剛中で進まず、みずから車の軸を外す。中で自ら止められれば、人に止められる必要はない。自ら止める者は、その止まりが固い。"},
  "26-2": {"zh": "你在下卦最上面，与上九同德而前进，像良马追赶。要前进得有凭借，先练好自己的防卫再走——不练就走，就叫妄。", "en": "You're at the top of the lower trigram, advancing with the top line of like virtue, like a good horse in full gallop. To advance you need equipment — train your defenses before going. Going untrained is rashness.", "ja": "下卦の最上部にいて、上九と同じ徳で進み、駿馬が駆けるようだ。進むには支えが要る。自分の備えを習ってから行く——習わずに行くのを妄という。"},
  "26-3": {"zh": "你在上卦下面，在小牛还没长角时就止住它，防患在先。在事情没发生前禁止，用力少而功效多——制止坏事，贵在趁早。", "en": "You're below the upper trigram, restraining the young bull before its horns grow — preventing before it happens. Forbidding before the event takes little effort and achieves much. Checking evil values doing it early.", "ja": "上卦の下にいて、小牛に角が生える前に止める。患いを未然に防ぐことだ。事が起きる前に禁じれば、力は少なく功は多い。悪を制するのは早さが肝心。"},
  "26-4": {"zh": "你在尊位旁边，柔和中正而止住外物，去其势而不去其牙。制刚不制末节而制根本——根本去掉了，牙就不必怕了。", "en": "You're beside the place of honor, soft and centered, restraining things — removing their momentum, not their teeth. To control strength, address the root, not the tip. Once the root is gone, the teeth aren't frightening.", "ja": "尊位の傍らにいて、柔らかく中を得て物を止め、その勢いを除いて牙は除かない。剛を制するには末ではなく本を制する。本が除かれれば、牙は恐れるに足りない。"},
  "26-5": {"zh": "你到了卦的顶，畜到了头，止极而通，大道通行。畜到极处就通，先前止住的正是为了行——到了这里，无往而不达。", "en": "You're at the top of the hexagram, Chu at its end — restraint ending in opening, the great way running free. At the peak of accumulation things open; what was held back was for moving. At this point, nowhere you go won't reach.", "ja": "卦の頂点にいて、畜は終わり、止まりきって通じ、大道が行われる。畜めの極は通ずる——止めたのは、行くためだった。ここに至れば、行く先どこへでも届く。"},
}
